-- composition of rule kernels column_lifetime x disjunctive_join_rewriter (duckdb), template not_exists
SELECT count(*) FROM (FROM (VALUES (1, 2)) a(x, y) JOIN (VALUES (1, 2)) b( y) ON a.x JOIN (VALUES (1, 2)) c(x, y) ON a.x = c.x OR a.y = c.y) AS ka WHERE NOT EXISTS (SELECT 1 FROM (SELECT AGE ((MAX ('1999-12-31 23:59:59.999999+05:30'::timestamptz) OVER (PARTITION BY 16) - '-1 month'::interval), DATE_TRUNC ('year', (SELECT MIN ('1999-12-31 23:59:59.999999+05:30'::timestamptz) FROM t4 AS a1))) AS c0, 45 AS c1, 40 AS c2) AS kb);
-- pgfuzz:check kernel:not_exists SELECT CASE WHEN (SELECT count(*) FROM (SELECT AGE ((MAX ('1999-12-31 23:59:59.999999+05:30'::timestamptz) OVER (PARTITION BY 16) - '-1 month'::interval), DATE_TRUNC ('year', (SELECT MIN ('1999-12-31 23:59:59.999999+05:30'::timestamptz) FROM t4 AS a1))) AS c0, 45 AS c1, 40 AS c2) AS kb) = 0 THEN (SELECT count(*) FROM (FROM (VALUES (1, 2)) a(x, y) JOIN (VALUES (1, 2)) b( y) ON a.x JOIN (VALUES (1, 2)) c(x, y) ON a.x = c.x OR a.y = c.y) AS ka) ELSE 0 END
